3	import android.graphics.PointF;
4	
5	import com.airbnb.lottie.LottieComposition;
6	import com.airbnb.lottie.model.animatable.AnimatableFloatValue;
7	import com.airbnb.lottie.model.animatable.AnimatablePathValue;
8	import com.airbnb.lottie.model.animatable.AnimatableSplitDimensionPathValue;
9	import com.airbnb.lottie.model.animatable.AnimatableValue;
10	import com.airbnb.lottie.parser.moshi.JsonReader;
11	import com.airbnb.lottie.utils.Utils;
12	import com.airbnb.lottie.value.Keyframe;
13	
14	import java.io.IOException;
15	import java.util.ArrayList;
16	import java.util.List;
17	
18	public class AnimatablePathValueParser {
19	
20	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
21	      "k",
22	      "x",
23	      "y"
24	  );
25	
26	  private AnimatablePathValueParser() {
27	  }
28	
29	  public static AnimatablePathValue parse(
30	      JsonReader reader, LottieComposition composition) throws IOException {
31	    List<Keyframe<PointF>> keyframes = new ArrayList<>();
32	    if (reader.peek() == JsonReader.Token.BEGIN_ARRAY) {
33	      reader.beginArray();
34	      while (reader.hasNext()) {
35	        keyframes.add(PathKeyframeParser.parse(reader, composition));
36	      }
37	      reader.endArray();
38	      KeyframesParser.setEndFrames(keyframes);
39	    } else {
40	      keyframes.add(new Keyframe<>(JsonUtils.jsonToPoint(reader, Utils.dpScale())));
41	    }
42	    return new AnimatablePathValue(keyframes);
43	  }
44	
45	  /**
46	   * Returns either an {@link AnimatablePathValue} or an {@link AnimatableSplitDimensionPathValue}.
47	   */
48	  static AnimatableValue<PointF, PointF> parseSplitPath(
49	      JsonReader reader, LottieComposition composition) throws IOException {
50	
51	    AnimatablePathValue pathAnimation = null;
52	    AnimatableFloatValue xAnimation = null;
53	    AnimatableFloatValue yAnimation = null;
54	
55	    boolean hasExpressions = false;
56	
57	    reader.beginObject();
58	    while (reader.peek() != JsonReader.Token.END_OBJECT) {
59	      switch (reader.selectName(NAMES)) {
60	        case 0:
61	          pathAnimation = AnimatablePathValueParser.parse(reader, composition);
62	          break;
63	        case 1:
64	          if (reader.peek() == JsonReader.Token.STRING) {
65	            hasExpressions = true;
66	            reader.skipValue();
67	          } else {
68	            xAnimation = AnimatableValueParser.parseFloat(reader, composition);
69	          }
70	          break;
71	        case 2:
72	          if (reader.peek() == JsonReader.Token.STRING) {
73	            hasExpressions = true;
74	            reader.skipValue();
75	          } else {
76	            yAnimation = AnimatableValueParser.parseFloat(reader, composition);
77	          }
78	          break;
79	        default:
80	          reader.skipName();
81	          reader.skipValue();
82	      }
83	    }
84	    reader.endObject();
85	
86	    if (hasExpressions) {
87	      composition.addWarning("Lottie doesn't support expressions.");
88	    }
89	
90	    if (pathAnimation != null) {
91	      return pathAnimation;
92	    }
93	    return new AnimatableSplitDimensionPathValue(xAnimation, yAnimation);
94	  }
95	
96	}
