12	
13	class CircleShapeParser {
14	
15	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
16	      "nm",
17	      "p",
18	      "s",
19	      "hd",
20	      "d"
21	  );
22	
23	  private CircleShapeParser() {
24	  }
25	
26	  static CircleShape parse(
27	      JsonReader reader, LottieComposition composition, int d) throws IOException {
28	    String name = null;
29	    AnimatableValue<PointF, PointF> position = null;
30	    AnimatablePointValue size = null;
31	    boolean reversed = d == 3;
32	    boolean hidden = false;
33	
34	    while (reader.hasNext()) {
35	      switch (reader.selectName(NAMES)) {
36	        case 0:
37	          name = reader.nextString();
38	          break;
39	        case 1:
40	          position = AnimatablePathValueParser.parseSplitPath(reader, composition);
41	          break;
42	        case 2:
43	          size = AnimatableValueParser.parsePoint(reader, composition);
44	          break;
45	        case 3:
46	          hidden = reader.nextBoolean();
47	          break;
48	        case 4:
49	          // "d" is 2 for normal and 3 for reversed.
50	          reversed = reader.nextInt() == 3;
51	          break;
52	        default:
53	          reader.skipName();
54	          reader.skipValue();
55	      }
56	    }
57	
58	    return new CircleShape(name, position, size, reversed, hidden);
59	  }
60	}
