11	
12	public class DocumentDataParser implements ValueParser<DocumentData> {
13	  public static final DocumentDataParser INSTANCE = new DocumentDataParser();
14	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
15	      "t",  // 0
16	      "f",  // 1
17	      "s",  // 2
18	      "j",  // 3
19	      "tr", // 4
20	      "lh", // 5
21	      "ls", // 6
22	      "fc", // 7
23	      "sc", // 8
24	      "sw", // 9
25	      "of", // 10
26	      "ps", // 11
27	      "sz" // 12
28	  );
29	
30	  private DocumentDataParser() {
31	  }
32	
33	  @Override
34	  public DocumentData parse(JsonReader reader, float scale) throws IOException {
35	    String text = null;
36	    String fontName = null;
37	    float size = 0f;
38	    Justification justification = Justification.CENTER;
39	    int tracking = 0;
40	    float lineHeight = 0f;
41	    float baselineShift = 0f;
42	    int fillColor = 0;
43	    int strokeColor = 0;
44	    float strokeWidth = 0f;
45	    boolean strokeOverFill = true;
46	    PointF boxPosition = null;
47	    PointF boxSize = null;
48	
49	    reader.beginObject();
50	    while (reader.hasNext()) {
51	      switch (reader.selectName(NAMES)) {
52	        case 0:
53	          text = reader.nextString();
54	          break;
55	        case 1:
56	          fontName = reader.nextString();
57	          break;
58	        case 2:
59	          size = (float) reader.nextDouble();
60	          break;
61	        case 3:
62	          int justificationInt = reader.nextInt();
63	          if (justificationInt > Justification.CENTER.ordinal() || justificationInt < 0) {
64	            justification = Justification.CENTER;
65	          } else {
66	            justification = Justification.values()[justificationInt];
67	          }
68	          break;
69	        case 4:
70	          tracking = reader.nextInt();
71	          break;
72	        case 5:
73	          lineHeight = (float) reader.nextDouble();
74	          break;
75	        case 6:
76	          baselineShift = (float) reader.nextDouble();
77	          break;
78	        case 7:
79	          fillColor = JsonUtils.jsonToColor(reader);
80	          break;
81	        case 8:
82	          strokeColor = JsonUtils.jsonToColor(reader);
83	          break;
84	        case 9:
85	          strokeWidth = (float) reader.nextDouble();
86	          break;
87	        case 10:
88	          strokeOverFill = reader.nextBoolean();
89	          break;
90	        case 11:
91	          reader.beginArray();
92	          boxPosition = new PointF((float) reader.nextDouble() * scale, (float) reader.nextDouble() * scale);
93	          reader.endArray();
94	          break;
95	        case 12:
96	          reader.beginArray();
97	          boxSize = new PointF((float) reader.nextDouble() * scale, (float) reader.nextDouble() * scale);
98	          reader.endArray();
99	          break;
100	        default:
101	          reader.skipName();
102	          reader.skipValue();
103	      }
104	    }
105	    reader.endObject();
106	
107	    return new DocumentData(text, fontName, size, justification, tracking, lineHeight,
108	        baselineShift, fillColor, strokeColor, strokeWidth, strokeOverFill, boxPosition, boxSize);
109	  }
110	}
