30	    AnimatableColorValue color = null;
31	    boolean fillEnabled = false;
32	    AnimatableIntegerValue opacity = null;
33	    String name = null;
34	    int fillTypeInt = 1;
35	    boolean hidden = false;
36	
37	    while (reader.hasNext()) {
38	      switch (reader.selectName(NAMES)) {
39	        case 0:
40	          name = reader.nextString();
41	          break;
42	        case 1:
43	          color = AnimatableValueParser.parseColor(reader, composition);
44	          break;
45	        case 2:
46	          opacity = AnimatableValueParser.parseInteger(reader, composition);
47	          break;
48	        case 3:
49	          fillEnabled = reader.nextBoolean();
50	          break;
51	        case 4:
52	          fillTypeInt = reader.nextInt();
53	          break;
54	        case 5:
55	          hidden = reader.nextBoolean();
56	          break;
57	        default:
58	          reader.skipName();
59	          reader.skipValue();
60	      }
61	    }
62	
63	    // Telegram sometimes omits opacity.
64	    // https://github.com/airbnb/lottie-android/issues/1600
65	    opacity = opacity == null ? new AnimatableIntegerValue(Collections.singletonList(new Keyframe<>(100))) : opacity;
