11	
12	import java.io.IOException;
13	import java.util.ArrayList;
14	import java.util.Collections;
15	import java.util.List;
16	
17	class ShapeStrokeParser {
18	
19	  private static final JsonReader.Options NAMES = JsonReader.Options.of(
20	      "nm",
21	      "c",
22	      "w",
23	      "o",
24	      "lc",
25	      "lj",
26	      "ml",
27	      "hd",
28	      "d"
29	  );
30	  private static final JsonReader.Options DASH_PATTERN_NAMES = JsonReader.Options.of(
31	      "n",
32	      "v"
33	  );
34	
35	  private ShapeStrokeParser() {
36	  }
37	
38	  static ShapeStroke parse(
39	      JsonReader reader, LottieComposition composition) throws IOException {
40	    String name = null;
41	    AnimatableColorValue color = null;
42	    AnimatableFloatValue width = null;
43	    AnimatableIntegerValue opacity = null;
44	    ShapeStroke.LineCapType capType = null;
45	    ShapeStroke.LineJoinType joinType = null;
46	    AnimatableFloatValue offset = null;
47	    float miterLimit = 0f;
48	    boolean hidden = false;
49	
50	    List<AnimatableFloatValue> lineDashPattern = new ArrayList<>();
51	
52	    while (reader.hasNext()) {
53	      switch (reader.selectName(NAMES)) {
54	        case 0:
55	          name = reader.nextString();
56	          break;
57	        case 1:
58	          color = AnimatableValueParser.parseColor(reader, composition);
59	          break;
60	        case 2:
61	          width = AnimatableValueParser.parseFloat(reader, composition);
62	          break;
63	        case 3:
64	          opacity = AnimatableValueParser.parseInteger(reader, composition);
65	          break;
66	        case 4:
67	          capType = ShapeStroke.LineCapType.values()[reader.nextInt() - 1];
68	          break;
69	        case 5:
70	          joinType = ShapeStroke.LineJoinType.values()[reader.nextInt() - 1];
71	          break;
72	        case 6:
73	          miterLimit = (float) reader.nextDouble();
74	          break;
75	        case 7:
76	          hidden = reader.nextBoolean();
77	          break;
78	        case 8:
79	          reader.beginArray();
80	          while (reader.hasNext()) {
81	            String n = null;
82	            AnimatableFloatValue val = null;
83	
84	            reader.beginObject();
85	            while (reader.hasNext()) {
86	              switch (reader.selectName(DASH_PATTERN_NAMES)) {
87	                case 0:
88	                  n = reader.nextString();
89	                  break;
90	                case 1:
91	                  val = AnimatableValueParser.parseFloat(reader, composition);
92	                  break;
93	                default:
94	                  reader.skipName();
95	                  reader.skipValue();
96	              }
97	            }
98	            reader.endObject();
99	
100	            switch (n) {
101	              case "o":
102	                offset = val;
103	                break;
104	              case "d":
105	              case "g":
106	                composition.setHasDashPattern(true);
107	                lineDashPattern.add(val);
108	                break;
109	            }
110	          }
111	          reader.endArray();
112	
113	          if (lineDashPattern.size() == 1) {
114	            // If there is only 1 value then it is assumed to be equal parts on and off.
115	            lineDashPattern.add(lineDashPattern.get(0));
116	          }
117	          break;
118	        default:
119	          reader.skipValue();
120	      }
121	    }
122	
123	    // Telegram sometimes omits opacity.
124	    // https://github.com/airbnb/lottie-android/issues/1600
125	    opacity = opacity == null ? new AnimatableIntegerValue(Collections.singletonList(new Keyframe<>(100))) : opacity;
126	    // Unclear why these are omitted sometimes but default to After Effects default value
127	    // https://github.com/airbnb/lottie-android/issues/2325
128	    capType = capType == null ? ShapeStroke.LineCapType.BUTT : capType;
129	    joinType = joinType == null ? ShapeStroke.LineJoinType.MITER : joinType;
130	    return new ShapeStroke(
131	        name, offset, lineDashPattern, color, opacity, width, capType, joinType, miterLimit, hidden);
132	  }
133	}
