15	@RestrictTo(RestrictTo.Scope.LIBRARY)
16	public class DefaultLottieFetchResult implements LottieFetchResult {
17	
18	  @NonNull
19	  private final HttpURLConnection connection;
20	
21	  public DefaultLottieFetchResult(@NonNull HttpURLConnection connection) {
22	    this.connection = connection;
23	  }
24	
25	  @Override public boolean isSuccessful() {
26	    try {
27	      return connection.getResponseCode() / 100 == 2;
28	    } catch (IOException e) {
29	      return false;
30	    }
31	  }
32	
33	  @NonNull @Override public InputStream bodyByteStream() throws IOException {
34	    return connection.getInputStream();
35	  }
36	
37	  @Nullable @Override public String contentType() {
38	    return connection.getContentType();
39	  }
40	
41	  @Nullable @Override public String error() {
42	    try {
43	      return isSuccessful() ? null :
44	          "Unable to fetch " + connection.getURL() + ". Failed with " + connection.getResponseCode() + "\n" + getErrorFromConnection(connection);
45	    } catch (IOException | NullPointerException e) {
46	      Logger.warning("get error failed ", e);
47	      return e.getMessage();
48	    }
49	  }
50	
51	  @Override public void close() {
52	    connection.disconnect();
53	  }
54	
55	  private String getErrorFromConnection(HttpURLConnection connection) throws IOException {
56	    BufferedReader r = new BufferedReader(new InputStreamReader(connection.getErrorStream()));
57	    StringBuilder error = new StringBuilder();
58	    String line;
59	
60	    try {
61	      while ((line = r.readLine()) != null) {
62	        error.append(line).append('\n');
63	      }
64	    } finally {
65	      try {
66	        r.close();
67	      } catch (Exception e) {
68	        // Do nothing.
69	      }
70	    }
71	    return error.toString();
72	  }
73	}
