1	package com.airbnb.lottie.utils;
2	
3	import android.graphics.Matrix;
4	import android.graphics.PointF;
5	
6	/**
7	 * 3D transformation utility class that mimics iOS CATransform3D implementation
8	 * Provides more accurate 3D rotation calculations, especially for Z-axis rotation
9	 */
10	public class Transform3D {
11	
12	    /**
13	     * Applies 3D transformation to the given matrix following Lottie Android's transformation order
14	     * This method reuses the provided matrix to avoid object allocation
15	     *
16	     * @param outMatrix Output matrix to receive the transformation
17	     * @param anchor Anchor point
18	     * @param position Position
19	     * @param scaleX X-axis scale
20	     * @param scaleY Y-axis scale
21	     * @param rotationX X-axis rotation (degrees)
22	     * @param rotationY Y-axis rotation (degrees)
23	     * @param rotationZ Z-axis rotation (degrees)
24	     * @param preComputedCosX Pre-computed cos(rotationX) to avoid redundant calculation
25	     * @param preComputedCosY Pre-computed cos(rotationY) to avoid redundant calculation
26	     */
27	    public static void applyTransform(
28	            Matrix outMatrix,
29	            PointF anchor,
30	            PointF position,
31	            float scaleX,
32	            float scaleY,
33	            float rotationX,
34	            float rotationY,
35	            float rotationZ,
36	            float preComputedCosX,
37	            float preComputedCosY) {
38	
39	        outMatrix.reset();
40	
41	        // Follow original Lottie Android order: position → rotation → scale → anchor
42	
43	        // 1. Apply position transformation
44	        if (position != null && (position.x != 0 || position.y != 0)) {
45	            outMatrix.preTranslate(position.x, position.y);
46	        }
47	
48	        // 2. Apply 3D rotation (rotate directly without anchor, as anchor is handled at the end)
49	        if (rotationZ != 0) {
50	          outMatrix.preRotate(rotationZ);
51	        }
52	        if (rotationY != 0) {
53	          applyYRotation(outMatrix, preComputedCosY);
54	        }
55	        if (rotationX != 0) {
56	          applyXRotation(outMatrix, preComputedCosX);
57	        }
58	
59	        // 3. Apply scale (Note: Lottie's scale doesn't need to be divided by 100, use ScaleXY values directly)
60	        if (scaleX != 1.0f || scaleY != 1.0f) {
61	            outMatrix.preScale(scaleX, scaleY);
62	        }
63	
64	        // 4. Finally translate to negative anchor position (consistent with original code)
65	        if (anchor != null && (anchor.x != 0 || anchor.y != 0)) {
66	            outMatrix.preTranslate(-anchor.x, -anchor.y);
67	        }
68	    }
69	
70	    /**
71	     * Apply 3D rotations (X, Y, Z) to the matrix
72	     * This method can be used independently for repeater or other scenarios
73	     *
74	     * @param matrix Output matrix to receive the rotation transformation
75	     * @param rotationX X-axis rotation in degrees
76	     * @param rotationY Y-axis rotation in degrees
77	     * @param rotationZ Z-axis rotation in degrees
78	     * @param preComputedCosX Pre-computed cos(rotationX) to avoid redundant calculation
79	     * @param preComputedCosY Pre-computed cos(rotationY) to avoid redundant calculation
80	     */
81	    public static void apply3DRotations(
82	            Matrix matrix,
83	            float rotationX,
84	            float rotationY,
85	            float rotationZ,
86	            float preComputedCosX,
87	            float preComputedCosY) {
88	
89	        // Apply rotations in order: Z -> Y -> X
90	        if (rotationZ != 0) {
91	            matrix.preRotate(rotationZ);
92	        }
93	        if (rotationY != 0) {
94	            applyYRotation(matrix, preComputedCosY);
95	        }
96	        if (rotationX != 0) {
97	            applyXRotation(matrix, preComputedCosX);
98	        }
99	    }
100	
101	    /**
102	     * Apply X-axis rotation using pre-computed cosine value
103	     * On a 2D plane, X-axis rotation primarily affects Y-direction scaling
104	     * Optimized version that directly modifies matrix values to avoid allocation
105	     *
106	     * @param matrix Input/output matrix to be modified
107	     * @param cosX Pre-computed cos(rotationX) value
108	     */
109	    private static void applyXRotation(Matrix matrix, float cosX) {
110	        // X-axis rotation is primarily represented as Y-direction perspective scaling in 2D projection
111	        // Directly scale Y-direction without matrix copy
112	        matrix.preScale(1f, cosX);
113	    }
114	
115	    /**
116	     * Apply Y-axis rotation using pre-computed cosine value
117	     * On a 2D plane, Y-axis rotation primarily affects X-direction scaling
118	     * Optimized version that directly modifies matrix values to avoid allocation
119	     *
120	     * @param matrix Input/output matrix to be modified
121	     * @param cosY Pre-computed cos(rotationY) value
122	     */
123	    private static void applyYRotation(Matrix matrix, float cosY) {
124	        // Y-axis rotation is primarily represented as X-direction perspective scaling in 2D projection
125	        // Directly scale X-direction without matrix copy
126	        matrix.preScale(cosY, 1f);
127	    }
128	    
129	    /**
130	     * Check if there is 3D transformation
131	     */
132	    public static boolean has3DRotation(Float rotationX, Float rotationY, Float rotationZ) {
133	        return (rotationX != null && rotationX != 0) ||
134	               (rotationY != null && rotationY != 0) ||
135	               (rotationZ != null && rotationZ != 0);
136	    }
137	}
