24	    this.dx = dx;
25	    this.dy = dy;
26	    this.color = color;
27	    this.vecs = null;
28	  }
29	
30	  public DropShadow(DropShadow other) {
31	    this.radius = other.radius;
32	    this.dx = other.dx;
33	    this.dy = other.dy;
34	    this.color = other.color;
35	    this.vecs = null;
36	  }
