70	  public boolean sameAs(DropShadow other) {
71	    return radius == other.radius && dx == other.dx && dy == other.dy && color == other.color;
72	  }
73	
74	  public void transformBy(Matrix matrix) {
75	    if (vecs == null) vecs = new float[2];
76	    vecs[0] = dx;
77	    vecs[1] = dy;
78	    matrix.mapVectors(vecs);
79	
80	    dx = vecs[0];
81	    dy = vecs[1];
82	    radius = matrix.mapRadius(radius);
83	  }
84	
85	  public void multiplyOpacity(int newAlpha) {
86	    int opacity = Math.round(Color.alpha(color) * MiscUtils.clamp(newAlpha, 0, 255) / 255f);
87	    color = Color.argb(opacity, Color.red(color), Color.green(color), Color.blue(color));
88	  }
89	
90	  /**
91	   * Applies a shadow to the provided Paint object.
92	   */
93	  public void applyTo(Paint paint) {
94	    if (Color.alpha(color) > 0) {
95	      // Paint.setShadowLayer() removes the shadow if radius is 0, so we use a small nonzero value in that case
96	      paint.setShadowLayer(Math.max(radius, Float.MIN_VALUE), dx, dy, color);
97	    } else {
98	      paint.clearShadowLayer();
99	    }
100	  }
101	
102	  /**
103	   * Applies a shadow to the provided Paint object, mixing its alpha by the provided value.
104	   */
105	  public void applyWithAlpha(int alpha, Paint paint) {
106	    int finalAlpha = Utils.mixOpacities(Color.alpha(color), MiscUtils.clamp(alpha, 0, 255));
107	    if (finalAlpha > 0) {
108	      int newColor = Color.argb(finalAlpha, Color.red(color), Color.green(color), Color.blue(color));
109	      // Paint.setShadowLayer() removes the shadow if radius is 0, so we use a small nonzero value in that case
110	      paint.setShadowLayer(Math.max(radius, Float.MIN_VALUE), dx, dy, newColor);
111	    } else {
112	      paint.clearShadowLayer();
113	    }
114	  }
115	
116	  /**
117	   * Applies a shadow to the provided ComposeOp, mixing its alpha by the provided value.
118	   */
119	  public void applyWithAlpha(int alpha, OffscreenLayer.ComposeOp op) {
120	    op.shadow = new DropShadow(this);
121	    op.shadow.multiplyOpacity(alpha);
122	  }
123	
124	  /**
125	   * Applies a shadow to the provided ComposeOp, to be used with OffscreenLayer.
126	   */
127	  public void applyTo(OffscreenLayer.ComposeOp op) {
128	    if (Color.alpha(color) > 0) {
129	      op.shadow = this;
130	    } else {
131	      op.shadow = null;
132	    }
133	  }
134	}
