300	  @Override public void invalidate() {
301	    super.invalidate();
302	    Drawable d = getDrawable();
303	    if (d instanceof LottieDrawable && ((LottieDrawable) d).getRenderMode() == RenderMode.SOFTWARE) {
304	      // This normally isn't needed. However, when using software rendering, Lottie caches rendered bitmaps
305	      // and updates it when the animation changes internally.
306	      // If you have dynamic properties with a value callback and want to update the value of the dynamic property, you need a way
307	      // to tell Lottie that the bitmap is dirty and it needs to be re-rendered. Normal drawables always re-draw the actual shapes
308	      // so this isn't an issue but for this path, we have to take the extra step of setting the dirty flag.
309	      lottieDrawable.invalidateSelf();
310	    }
311	  }
