655	  /**
656	   * Sets a composition.
657	   * You can set a default cache strategy if this view was inflated with xml by
658	   * using {@link R.attr#lottie_cacheComposition}.
659	   */
660	  public void setComposition(@NonNull LottieComposition composition) {
661	    if (L.DBG) {
662	      Log.v(TAG, "Set Composition \n" + composition);
663	    }
664	    lottieDrawable.setCallback(this);
665	
666	    ignoreUnschedule = true;
667	    boolean isNewComposition = lottieDrawable.setComposition(composition);
668	    if (autoPlay) {
669	      lottieDrawable.playAnimation();
670	    }
671	    ignoreUnschedule = false;
672	    if (getDrawable() == lottieDrawable && !isNewComposition) {
673	      // We can avoid re-setting the drawable, and invalidating the view, since the composition
674	      // hasn't changed.
675	      return;
676	    } else if (!isNewComposition) {
677	      // The current drawable isn't lottieDrawable but the drawable already has the right composition.
678	      setLottieDrawable();
679	    }
680	
681	    // This is needed to makes sure that the animation is properly played/paused for the current visibility state.
682	    // It is possible that the drawable had a lazy composition task to play the animation but this view subsequently
683	    // became invisible. Comment this out and run the espresso tests to see a failing test.
684	    onVisibilityChanged(this, getVisibility());
685	
686	    requestLayout();
