10	import com.airbnb.lottie.value.LottieValueCallback;
11	
12	
13	public class DropShadowKeyframeAnimation implements BaseKeyframeAnimation.AnimationListener {
14	
15	  private static final float DEG_TO_RAD = (float) (Math.PI / 180.0);
16	
17	  // We scale the "Softness" value by a constant factor so that the Paint.setShadowLayer() call
18	  // gives results that more closely match After Effects
19	  private static final float AFTER_EFFECT_SOFTNESS_SCALE_FACTOR = 0.33f;
20	
21	  private final BaseLayer layer;
22	  private final BaseKeyframeAnimation.AnimationListener listener;
23	  private final BaseKeyframeAnimation<Integer, Integer> color;
24	  private final FloatKeyframeAnimation opacity;
25	  private final FloatKeyframeAnimation direction;
26	  private final FloatKeyframeAnimation distance;
27	  private final FloatKeyframeAnimation radius;
28	
29	  @Nullable private Matrix layerInvMatrix;
30	
31	  public DropShadowKeyframeAnimation(BaseKeyframeAnimation.AnimationListener listener, BaseLayer layer, DropShadowEffect dropShadowEffect) {
32	    this.listener = listener;
33	    this.layer = layer;
34	    color = dropShadowEffect.getColor().createAnimation();
35	    color.addUpdateListener(this);
36	    layer.addAnimation(color);
37	    opacity = dropShadowEffect.getOpacity().createAnimation();
38	    opacity.addUpdateListener(this);
39	    layer.addAnimation(opacity);
40	    direction = dropShadowEffect.getDirection().createAnimation();
41	    direction.addUpdateListener(this);
42	    layer.addAnimation(direction);
43	    distance = dropShadowEffect.getDistance().createAnimation();
44	    distance.addUpdateListener(this);
45	    layer.addAnimation(distance);
46	    radius = dropShadowEffect.getRadius().createAnimation();
47	    radius.addUpdateListener(this);
48	    layer.addAnimation(radius);
49	  }
50	
51	  @Override public void onValueChanged() {
52	    listener.onValueChanged();
53	  }
54	
55	  public DropShadow evaluate(Matrix parentMatrix, int parentAlpha) {
56	    float directionRad = this.direction.getFloatValue() * DEG_TO_RAD;
57	    float distance = this.distance.getValue();
58	    float rawX = ((float) Math.sin(directionRad)) * distance;
59	    float rawY = ((float) Math.cos(directionRad + Math.PI)) * distance;
60	    float rawRadius = radius.getValue();
61	
62	    int baseColor = color.getValue();
63	    int opacity = Math.round(this.opacity.getValue() * parentAlpha / 255f);
64	    int shadowColor = Color.argb(opacity, Color.red(baseColor), Color.green(baseColor), Color.blue(baseColor));
65	
66	    DropShadow shadow = new DropShadow(rawRadius * AFTER_EFFECT_SOFTNESS_SCALE_FACTOR, rawX, rawY, shadowColor);
67	    shadow.transformBy(parentMatrix);
68	
69	    // Since the shadow parameters are relative to the layer on which the shadow resides, correct for this
70	    // by undoing the layer's own transform. For example, if the layer is scaled, the screen-space blur
71	    // radius should stay constant.
72	    if (layerInvMatrix == null) layerInvMatrix = new Matrix();
73	    layer.transform.getMatrix().invert(layerInvMatrix);
74	    shadow.transformBy(layerInvMatrix);
75	
76	    return shadow;
77	  }
78	
79	  public void setColorCallback(@Nullable LottieValueCallback<Integer> callback) {
80	    color.setValueCallback(callback);
81	  }
82	
83	  public void setOpacityCallback(@Nullable final LottieValueCallback<Float> callback) {
84	    if (callback == null) {
85	      opacity.setValueCallback(null);
86	      return;
87	    }
88	    opacity.setValueCallback(new LottieValueCallback<Float>() {
89	      @Nullable
90	      @Override
91	      public Float getValue(LottieFrameInfo<Float> frameInfo) {
92	        Float value = callback.getValue(frameInfo);
93	        if (value == null) {
94	          return null;
95	        }
96	        // Convert [0,100] to [0,255] because other dynamic properties use [0,100].
97	        return value * 2.55f;
98	      }
99	    });
100	  }
101	
102	  public void setDirectionCallback(@Nullable LottieValueCallback<Float> callback) {
103	    direction.setValueCallback(callback);
104	  }
105	
106	  public void setDistanceCallback(@Nullable LottieValueCallback<Float> callback) {
107	    distance.setValueCallback(callback);
108	  }
109	
110	  public void setRadiusCallback(@Nullable LottieValueCallback<Float> callback) {
111	    radius.setValueCallback(callback);
112	  }
113	}
