640	    userActionsTaken.add(UserActionTaken.SET_ANIMATION);
641	    clearComposition();
642	    cancelLoaderTask();
643	    this.compositionTask = compositionTask
644	        .addListener(loadedListener)
645	        .addFailureListener(wrappedFailureListener);
646	  }
