21	  @Nullable
22	  static BlurEffect parse(JsonReader reader, LottieComposition composition) throws IOException {
23	    BlurEffect blurEffect = null;
24	    while (reader.hasNext()) {
25	      switch (reader.selectName(BLUR_EFFECT_NAMES)) {
