15	      "ef"
16	  );
17	  private static final JsonReader.Options INNER_EFFECT_NAMES = JsonReader.Options.of(
18	      "nm",
19	      "v"
20	  );
21	
22	  private AnimatableColorValue color;
23	  private AnimatableFloatValue opacity;
24	  private AnimatableFloatValue direction;
25	  private AnimatableFloatValue distance;
26	  private AnimatableFloatValue radius;
27	
28	  @Nullable
29	  DropShadowEffect parse(JsonReader reader, LottieComposition composition) throws IOException {
30	    while (reader.hasNext()) {
31	      switch (reader.selectName(DROP_SHADOW_EFFECT_NAMES)) {
32	        case 0:
33	          reader.beginArray();
34	          while (reader.hasNext()) {
35	            maybeParseInnerEffect(reader, composition);
36	          }
37	          reader.endArray();
38	          break;
39	        default:
40	          reader.skipName();
41	          reader.skipValue();
42	      }
43	    }
44	    if (color != null && opacity != null && direction != null && distance != null && radius != null) {
45	      return new DropShadowEffect(color, opacity, direction, distance, radius);
