50	  private void maybeParseInnerEffect(JsonReader reader, LottieComposition composition) throws IOException {
51	    String currentEffectName = "";
52	    reader.beginObject();
53	    while (reader.hasNext()) {
54	      switch (reader.selectName(INNER_EFFECT_NAMES)) {
55	        case 0:
56	          currentEffectName = reader.nextString();
57	          break;
58	        case 1:
59	          switch (currentEffectName) {
60	            case "Shadow Color":
61	              color = AnimatableValueParser.parseColor(reader, composition);
62	              break;
63	            case "Opacity":
64	              opacity = AnimatableValueParser.parseFloat(reader, composition, false);
65	              break;
66	            case "Direction":
67	              direction = AnimatableValueParser.parseFloat(reader, composition, false);
68	              break;
69	            case "Distance":
70	              distance = AnimatableValueParser.parseFloat(reader, composition);
71	              break;
72	            case "Softness":
73	              radius = AnimatableValueParser.parseFloat(reader, composition);
74	              break;
75	            default:
76	              reader.skipValue();
77	              break;
78	          }
79	          break;
80	        default:
81	          reader.skipName();
82	          reader.skipValue();
83	      }
84	    }
85	    reader.endObject();
