12	class MaskParser {
13	
14	  private MaskParser() {
15	  }
16	
17	  static Mask parse(
18	      JsonReader reader, LottieComposition composition) throws IOException {
19	    Mask.MaskMode maskMode = null;
20	    AnimatableShapeValue maskPath = null;
21	    AnimatableIntegerValue opacity = null;
22	    boolean inverted = false;
23	
24	    reader.beginObject();
25	    while (reader.hasNext()) {
26	      String mode = reader.nextName();
27	      switch (mode) {
28	        case "mode":
29	          switch (reader.nextString()) {
30	            case "a":
31	              maskMode = Mask.MaskMode.MASK_MODE_ADD;
32	              break;
33	            case "s":
34	              maskMode = Mask.MaskMode.MASK_MODE_SUBTRACT;
35	              break;
36	            case "n":
37	              maskMode = Mask.MaskMode.MASK_MODE_NONE;
38	              break;
39	            case "i":
40	              composition.addWarning(
41	                  "Animation contains intersect masks. They are not supported but will be treated like add masks.");
42	              maskMode = Mask.MaskMode.MASK_MODE_INTERSECT;
43	              break;
44	            default:
45	              Logger.warning("Unknown mask mode " + mode + ". Defaulting to Add.");
46	              maskMode = Mask.MaskMode.MASK_MODE_ADD;
47	          }
48	          break;
49	        case "pt":
50	          maskPath = AnimatableValueParser.parseShapeData(reader, composition);
51	          break;
52	        case "o":
53	          opacity = AnimatableValueParser.parseInteger(reader, composition);
54	          break;
55	        case "inv":
56	          inverted = reader.nextBoolean();
57	          break;
58	        default:
59	          reader.skipValue();
60	      }
61	    }
62	    reader.endObject();
63	
64	    return new Mask(maskMode, maskPath, opacity, inverted);
65	  }
66	
