26	public class ShapeLayer extends BaseLayer {
27	  private final ContentGroup contentGroup;
28	  private final CompositionLayer compositionLayer;
29	
30	  @Nullable private DropShadowKeyframeAnimation dropShadowAnimation;
31	
32	  ShapeLayer(LottieDrawable lottieDrawable, Layer layerModel, CompositionLayer compositionLayer, LottieComposition composition) {
33	    super(lottieDrawable, layerModel);
34	    this.compositionLayer = compositionLayer;
35	
36	    // Naming this __container allows it to be ignored in KeyPath matching.
37	    ShapeGroup shapeGroup = new ShapeGroup("__container", layerModel.getShapes(), false);
38	    contentGroup = new ContentGroup(lottieDrawable, this, shapeGroup, composition);
39	    contentGroup.setContents(Collections.<Content>emptyList(), Collections.<Content>emptyList());
40	
41	    if (getDropShadowEffect() != null) {
42	      dropShadowAnimation = new DropShadowKeyframeAnimation(this, this, getDropShadowEffect());
43	    }
44	  }
45	
46	  @Override void drawLayer(@NonNull Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow parentShadowToApply) {
47	    // If a parent composition layer has a shadow and we have one too, prioritize our own.
48	    DropShadow shadowToApply = dropShadowAnimation != null
49	        ? dropShadowAnimation.evaluate(parentMatrix, parentAlpha)
50	        : parentShadowToApply;
51	    contentGroup.draw(canvas, parentMatrix, parentAlpha, shadowToApply);
52	  }
53	
54	  @Override public void getBounds(RectF outBounds, Matrix parentMatrix, boolean applyParents) {
55	    super.getBounds(outBounds, parentMatrix, applyParents);
56	    contentGroup.getBounds(outBounds, boundsMatrix, applyParents);
57	  }
58	
59	  @Nullable @Override public BlurEffect getBlurEffect() {
60	    BlurEffect layerBlur = super.getBlurEffect();
61	    if (layerBlur != null) {
62	      return layerBlur;
63	    }
64	    return compositionLayer.getBlurEffect();
65	  }
66	
67	  @Override
68	  protected void resolveChildKeyPath(KeyPath keyPath, int depth, List<KeyPath> accumulator,
69	      KeyPath currentPartialKeyPath) {
70	    contentGroup.resolveKeyPath(keyPath, depth, accumulator, currentPartialKeyPath);
71	  }
72	
73	  @Override
74	  @CallSuper
75	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
76	    super.addValueCallback(property, callback);
77	    if (property == LottieProperty.DROP_SHADOW_COLOR && dropShadowAnimation != null) {
78	      dropShadowAnimation.setColorCallback((LottieValueCallback<Integer>) callback);
79	    } else if (property == LottieProperty.DROP_SHADOW_OPACITY && dropShadowAnimation != null) {
80	      dropShadowAnimation.setOpacityCallback((LottieValueCallback<Float>) callback);
81	    } else if (property == LottieProperty.DROP_SHADOW_DIRECTION && dropShadowAnimation != null) {
82	      dropShadowAnimation.setDirectionCallback((LottieValueCallback<Float>) callback);
83	    } else if (property == LottieProperty.DROP_SHADOW_DISTANCE && dropShadowAnimation != null) {
84	      dropShadowAnimation.setDistanceCallback((LottieValueCallback<Float>) callback);
85	    } else if (property == LottieProperty.DROP_SHADOW_RADIUS && dropShadowAnimation != null) {
86	      dropShadowAnimation.setRadiusCallback((LottieValueCallback<Float>) callback);
87	    }
88	  }
89	}
