2	
3	import androidx.annotation.CheckResult;
4	import androidx.annotation.Nullable;
5	import androidx.annotation.RestrictTo;
6	
7	import java.util.ArrayList;
8	import java.util.Arrays;
9	import java.util.List;
10	
11	/**
12	 * Defines which content to target.
13	 * The keypath can contain wildcards ('*') with match exactly 1 item.
14	 * or globstars ('**') which match 0 or more items. or KeyPath.COMPOSITION
15	 * to represent the root composition layer.
16	 * <p>
17	 * For example, if your content were arranged like this:
18	 * Gabriel (Shape Layer)
19	 * Body (Shape Group)
20	 * Left Hand (Shape)
21	 * Fill (Fill)
22	 * Transform (Transform)
23	 * ...
24	 * Brandon (Shape Layer)
25	 * Body (Shape Group)
26	 * Left Hand (Shape)
27	 * Fill (Fill)
28	 * Transform (Transform)
29	 * ...
30	 * <p>
31	 * <p>
32	 * You could:
33	 * Match Gabriel left hand fill:
34	 * new KeyPath("Gabriel", "Body", "Left Hand", "Fill");
35	 * Match Gabriel and Brandon's left hand fill:
36	 * new KeyPath("*", "Body", Left Hand", "Fill");
37	 * Match anything with the name Fill:
38	 * new KeyPath("**", "Fill");
39	 * Target the the root composition layer:
40	 * KeyPath.COMPOSITION
41	 * <p>
42	 * <p>
43	 * NOTE: Content that are part of merge paths or repeaters cannot currently be resolved with
44	 * a {@link KeyPath}. This may be fixed in the future.
45	 */
46	public class KeyPath {
47	  /**
48	   * A singleton KeyPath that targets on the root composition layer.
49	   * This is useful if you want to apply transformer to the animation as a whole.
50	   */
51	  public final static KeyPath COMPOSITION = new KeyPath("COMPOSITION");
52	
53	  private final List<String> keys;
54	  @Nullable private KeyPathElement resolvedElement;
55	
56	  public KeyPath(String... keys) {
57	    this.keys = Arrays.asList(keys);
58	  }
59	
60	  /**
61	   * Copy constructor. Copies keys as well.
62	   */
63	  private KeyPath(KeyPath keyPath) {
64	    keys = new ArrayList<>(keyPath.keys);
65	    resolvedElement = keyPath.resolvedElement;
66	  }
67	
68	  /**
69	   * Returns a new KeyPath with the key added.
70	   * This is used during keypath resolution. Children normally don't know about all of their parent
71	   * elements so this is used to keep track of the fully qualified keypath.
72	   * This returns a key keypath because during resolution, the full keypath element tree is walked
73	   * and if this modified the original copy, it would remain after popping back up the element tree.
74	   */
75	  @CheckResult
76	  @RestrictTo(RestrictTo.Scope.LIBRARY)
77	  public KeyPath addKey(String key) {
78	    KeyPath newKeyPath = new KeyPath(this);
79	    newKeyPath.keys.add(key);
80	    return newKeyPath;
81	  }
82	
83	  /**
84	   * Return a new KeyPath with the element resolved to the specified {@link KeyPathElement}.
85	   */
86	  @RestrictTo(RestrictTo.Scope.LIBRARY)
87	  public KeyPath resolve(KeyPathElement element) {
88	    KeyPath keyPath = new KeyPath(this);
89	    keyPath.resolvedElement = element;
90	    return keyPath;
91	  }
92	
93	  /**
94	   * Returns a {@link KeyPathElement} that this has been resolved to. KeyPaths get resolved with
95	   * resolveKeyPath on LottieDrawable or LottieAnimationView.
96	   */
97	  @RestrictTo(RestrictTo.Scope.LIBRARY)
98	  @Nullable
99	  public KeyPathElement getResolvedElement() {
100	    return resolvedElement;
101	  }
102	
103	  /**
104	   * Returns whether they key matches at the specified depth.
105	   */
106	  @SuppressWarnings("RedundantIfStatement")
107	  @RestrictTo(RestrictTo.Scope.LIBRARY)
108	  public boolean matches(String key, int depth) {
109	    if (isContainer(key)) {
110	      // This is an artificial layer we programatically create.
111	      return true;
112	    }
113	    if (depth >= keys.size()) {
114	      return false;
115	    }
116	    String keyAtDepth = keys.get(depth);
117	    if (keyAtDepth.equals(key) || keyAtDepth.equals("**") || keyAtDepth.equals("*")) {
118	      return true;
119	    }
120	    return false;
121	  }
122	
123	  /**
124	   * For a given key and depth, returns how much the depth should be incremented by when
125	   * resolving a keypath to children.
126	   * <p>
127	   * This can be 0 or 2 when there is a globstar and the next key either matches or doesn't match
128	   * the current key.
129	   */
130	  @RestrictTo(RestrictTo.Scope.LIBRARY)
131	  public int incrementDepthBy(String key, int depth) {
132	    if (isContainer(key)) {
133	      // If it's a container then we added programatically and it isn't a part of the keypath.
134	      return 0;
135	    }
136	    if (!keys.get(depth).equals("**")) {
137	      // If it's not a globstar then it is part of the keypath.
138	      return 1;
139	    }
140	    if (depth == keys.size() - 1) {
141	      // The last key is a globstar.
142	      return 0;
143	    }
144	    if (keys.get(depth + 1).equals(key)) {
145	      // We are a globstar and the next key is our current key so consume both.
146	      return 2;
147	    }
148	    return 0;
149	  }
150	
151	  /**
152	   * Returns whether the key at specified depth is fully specific enough to match the full set of
153	   * keys in this keypath.
154	   */
155	  @RestrictTo(RestrictTo.Scope.LIBRARY)
156	  public boolean fullyResolvesTo(String key, int depth) {
157	    if (depth >= keys.size()) {
158	      return false;
159	    }
160	    boolean isLastDepth = depth == keys.size() - 1;
161	    String keyAtDepth = keys.get(depth);
162	    boolean isGlobstar = keyAtDepth.equals("**");
163	
164	    if (!isGlobstar) {
165	      boolean matches = keyAtDepth.equals(key) || keyAtDepth.equals("*");
166	      return (isLastDepth || (depth == keys.size() - 2 && endsWithGlobstar())) && matches;
167	    }
168	
169	    boolean isGlobstarButNextKeyMatches = !isLastDepth && keys.get(depth + 1).equals(key);
170	    if (isGlobstarButNextKeyMatches) {
171	      return depth == keys.size() - 2 ||
172	          (depth == keys.size() - 3 && endsWithGlobstar());
173	    }
174	
175	    if (isLastDepth) {
176	      return true;
177	    }
178	    if (depth + 1 < keys.size() - 1) {
179	      // We are a globstar but there is more than 1 key after the globstar we we can't fully match.
180	      return false;
181	    }
182	    // Return whether the next key (which we now know is the last one) is the same as the current
183	    // key.
184	    return keys.get(depth + 1).equals(key);
185	  }
186	
187	  /**
188	   * Returns whether the keypath resolution should propagate to children. Some keypaths resolve
189	   * to content other than leaf contents (such as a layer or content group transform) so sometimes
190	   * this will return false.
191	   */
192	  @SuppressWarnings("SimplifiableIfStatement")
193	  @RestrictTo(RestrictTo.Scope.LIBRARY)
194	  public boolean propagateToChildren(String key, int depth) {
195	    if ("__container".equals(key)) {
196	      return true;
197	    }
198	    return depth < keys.size() - 1 || keys.get(depth).equals("**");
199	  }
200	
201	  /**
202	   * We artificially create some container groups (like a root ContentGroup for the entire animation
203	   * and for the contents of a ShapeLayer).
204	   */
205	  private boolean isContainer(String key) {
206	    return "__container".equals(key);
207	  }
208	
209	  private boolean endsWithGlobstar() {
210	    return keys.get(keys.size() - 1).equals("**");
211	  }
212	
213	  public String keysToString() {
214	    return keys.toString();
215	  }
216	
217	  @Override public boolean equals(Object o) {
218	    if (this == o) {
219	      return true;
220	    }
221	    if (o == null || getClass() != o.getClass()) {
222	      return false;
223	    }
224	
225	    KeyPath keyPath = (KeyPath) o;
226	
227	    if (!keys.equals(keyPath.keys)) {
228	      return false;
229	    }
230	    return resolvedElement != null ? resolvedElement.equals(keyPath.resolvedElement) : keyPath.resolvedElement == null;
231	  }
232	
233	  @Override public int hashCode() {
234	    int result = keys.hashCode();
235	    result = 31 * result + (resolvedElement != null ? resolvedElement.hashCode() : 0);
236	    return result;
237	  }
238	
239	  @Override public String toString() {
240	    return "KeyPath{" + "keys=" + keys + ",resolved=" + (resolvedElement != null) + '}';
241	  }
242	}
