14	  @Override public ScaleXY parse(JsonReader reader, float scale) throws IOException {
15	    boolean isArray = reader.peek() == JsonReader.Token.BEGIN_ARRAY;
16	    if (isArray) {
17	      reader.beginArray();
18	    }
19	    float sx = (float) reader.nextDouble();
20	    float sy = (float) reader.nextDouble();
21	    while (reader.hasNext()) {
22	      reader.skipValue();
23	    }
24	    if (isArray) {
25	      reader.endArray();
26	    }
27	    return new ScaleXY(sx / 100f * scale, sy / 100f * scale);
28	  }
