3	import android.graphics.PointF;
4	
5	import com.airbnb.lottie.parser.moshi.JsonReader;
6	
7	import java.io.IOException;
8	
9	public class PointFParser implements ValueParser<PointF> {
10	  public static final PointFParser INSTANCE = new PointFParser();
11	
12	  private PointFParser() {
13	  }
14	
15	  @Override
16	  public PointF parse(JsonReader reader, float scale) throws IOException {
17	    JsonReader.Token token = reader.peek();
18	    if (token == JsonReader.Token.BEGIN_ARRAY) {
19	      return JsonUtils.jsonToPoint(reader, scale);
20	    } else if (token == JsonReader.Token.BEGIN_OBJECT) {
21	      return JsonUtils.jsonToPoint(reader, scale);
22	    } else if (token == JsonReader.Token.NUMBER) {
23	      // This is the case where the static value for a property is an array of numbers.
24	      // We begin the array to see if we have an array of keyframes but it's just an array
25	      // of static numbers instead.
26	      PointF point = new PointF((float) reader.nextDouble() * scale, (float) reader.nextDouble() * scale);
27	      while (reader.hasNext()) {
28	        reader.skipValue();
29	      }
30	      return point;
31	    } else {
32	      throw new IllegalArgumentException("Cannot convert json to point. Next token is " + token);
33	    }
34	  }
35	}
